"""A stdlib stand-in for the Hugging Face hub, for tests that exercise the real downloader.

It answers the calls ``huggingface_hub`` 1.x makes to download a model: the model-info API
(``GET /api/models/<repo>[/revision/<rev>]`` with per-file sizes, blob ids and LFS metadata),
the recursive tree listing ``snapshot_download`` reads for the files to fetch
(``GET /api/models/<repo>/tree/<rev>``) and the file endpoint (``HEAD``/``GET /<repo>/resolve/<rev>/<file>`` with ``ETag``, ``X-Linked-*``,
``X-Repo-Commit`` and ``Range`` support). Files are generated bytes, so a test needs no network
and no model. A repository's blob names follow the real hub's rule (sha256 for an LFS file, the
git blob id for any other), which is what makes the byte-progress code testable.

Failure modes: ``ok``, ``401``, ``404``, ``500`` and ``slow`` (a large file stops after its first
chunk until the test sets ``hub.release``, so a test can read ``blobs/*.incomplete``
mid-download without sleeping).
"""

from __future__ import annotations

import hashlib
import json
import socket
import threading
from dataclasses import dataclass
from dataclasses import field
from http.server import BaseHTTPRequestHandler
from http.server import ThreadingHTTPServer
from typing import cast
from urllib.parse import unquote
from urllib.parse import urlparse

import pytest

COMMIT = "c" * 40
CHUNK = 64 * 1024
GATE_TIMEOUT_SECONDS = 30


@dataclass
class MockRepo:
    """One repository: its commit and files (name -> bytes); ``lfs`` names are served as LFS."""

    repo_id: str
    sha: str = COMMIT
    files: dict[str, bytes] = field(default_factory=dict)
    lfs: set[str] = field(default_factory=set)

    def blob_name(self, filename: str) -> str:
        """Return the cache blob name the real hub's etag rule gives this file."""
        data = self.files[filename]
        if filename in self.lfs:
            return hashlib.sha256(data).hexdigest()
        return hashlib.sha1(data, usedforsecurity=False).hexdigest()  # git blob id stand-in


def default_repo(repo_id: str, *, model_bytes: int = 2 * 1024 * 1024) -> MockRepo:
    """Return a repository shaped like a faster-whisper model, plus a file nobody downloads."""
    return MockRepo(
        repo_id=repo_id,
        files={
            "config.json": b'{"model": "mock"}',
            "preprocessor_config.json": b'{"feature_size": 80}',
            "model.bin": bytes(i % 251 for i in range(model_bytes)),
            "tokenizer.json": b'{"version": "1.0"}' * 40,
            "vocabulary.txt": b"hello\nworld\n" * 100,
            "README.md": b"# not downloaded\n" * 500,
        },
        lfs={"model.bin"},
    )


class _HubServer(ThreadingHTTPServer):
    """The HTTP server, carrying the hub it serves so the request handler can reach it."""

    hub: MockHfHub


class MockHfHub:
    """The running server. ``url`` is its endpoint; ``requests`` records what it was asked."""

    def __init__(self) -> None:
        self.repos: dict[str, MockRepo] = {}
        self.mode = "ok"
        self.release = threading.Event()
        self.requests: list[dict] = []
        self._server = _HubServer(("127.0.0.1", 0), _Handler)
        self._server.daemon_threads = True
        self._server.hub = self
        self.url = f"http://127.0.0.1:{self._server.server_address[1]}"
        self._thread = threading.Thread(target=self._server.serve_forever, daemon=True)

    def add_repo(self, repo: MockRepo) -> MockRepo:
        """Register a repository."""
        self.repos[repo.repo_id] = repo
        return repo

    def start(self) -> None:
        """Start serving on a free loopback port."""
        self._thread.start()

    def stop(self) -> None:
        """Stop serving and release the port."""
        self._server.shutdown()
        self._server.server_close()
        self._thread.join(timeout=5)

    def authorizations(self) -> list[str | None]:
        """Return the ``Authorization`` header of every request, in order."""
        return [r["authorization"] for r in self.requests]


_FAILURE_STATUS = {"401": 401, "404": 404, "500": 500}


class _Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    @property
    def hub(self) -> MockHfHub:
        return cast(_HubServer, self.server).hub

    def log_message(self, *_args) -> None:
        return

    def do_HEAD(self) -> None:
        self._route(head=True)

    def do_GET(self) -> None:
        self._route(head=False)

    def _send(self, status: int, body: bytes = b"", headers: dict | None = None) -> None:
        self.send_response(status)
        for key, value in (headers or {}).items():
            self.send_header(key, value)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body and self.command != "HEAD":
            self.wfile.write(body)

    def _route(self, *, head: bool) -> None:
        hub = self.hub
        hub.requests.append(
            {
                "method": self.command,
                "path": self.path,
                "authorization": self.headers.get("Authorization"),
            }
        )
        if hub.mode in _FAILURE_STATUS:
            code = _FAILURE_STATUS[hub.mode]
            self._send(code, b"{}", {"X-Error-Code": "RepoNotFound"} if code == 404 else {})
            return
        parts = [unquote(p) for p in urlparse(self.path).path.split("/") if p]
        if parts[:2] == ["api", "models"] and parts[4:5] == ["tree"]:
            self._tree(parts[2:4])
        elif parts[:2] == ["api", "models"]:
            self._model_info(parts[2:])
        elif "resolve" in parts:
            self._file(parts, head=head)
        else:
            self._send(404, b"{}")

    def _model_info(self, rest: list[str]) -> None:
        repo = self.hub.repos.get("/".join(rest[:2]))
        if repo is None:
            self._send(404, b"{}", {"X-Error-Code": "RepoNotFound"})
            return
        siblings = [_sibling(repo, name, data) for name, data in repo.files.items()]
        body = json.dumps(
            {
                "_id": "mock",
                "id": repo.repo_id,
                "modelId": repo.repo_id,
                "sha": repo.sha,
                "private": False,
                "siblings": siblings,
            }
        ).encode()
        self._send(200, body, {"Content-Type": "application/json"})

    def _tree(self, repo_parts: list[str]) -> None:
        repo = self.hub.repos.get("/".join(repo_parts))
        if repo is None:
            self._send(404, b"{}", {"X-Error-Code": "RepoNotFound"})
            return
        entries = [_tree_entry(repo, name, data) for name, data in repo.files.items()]
        self._send(200, json.dumps(entries).encode(), {"Content-Type": "application/json"})

    def _file(self, parts: list[str], *, head: bool) -> None:
        at = parts.index("resolve")
        repo = self.hub.repos.get("/".join(parts[:at]))
        filename = "/".join(parts[at + 2 :])
        if repo is None or filename not in repo.files:
            self._send(404, b"{}", {"X-Error-Code": "EntryNotFound"})
            return
        data = repo.files[filename]
        headers = _file_headers(repo, filename, data)
        if head:
            self.send_response(200)
            for key, value in {**headers, "Content-Length": str(len(data))}.items():
                self.send_header(key, value)
            self.end_headers()
            return
        start, status = 0, 200
        requested = self.headers.get("Range")
        if requested and requested.startswith("bytes="):
            start, status = int(requested[6:].split("-")[0] or 0), 206
            headers["Content-Range"] = f"bytes {start}-{len(data) - 1}/{len(data)}"
        self._stream(status, headers, data[start:])

    def _stream(self, status: int, headers: dict, body: bytes) -> None:
        self.send_response(status)
        for key, value in {**headers, "Content-Length": str(len(body))}.items():
            self.send_header(key, value)
        self.end_headers()
        if self.hub.mode != "slow":
            self.wfile.write(body)
            return
        for offset in range(0, len(body), CHUNK):
            self.wfile.write(body[offset : offset + CHUNK])
            self.wfile.flush()
            if offset == 0 and len(body) > CHUNK:
                # Hold a large file open after its first chunk until the test releases it, so
                # the test can read the .incomplete blob mid-download deterministically.
                self.hub.release.wait(timeout=GATE_TIMEOUT_SECONDS)


def _sibling(repo: MockRepo, name: str, data: bytes) -> dict:
    entry: dict = {
        "rfilename": name,
        "size": len(data),
        "blobId": hashlib.sha1(data, usedforsecurity=False).hexdigest(),
    }
    if name in repo.lfs:
        entry["lfs"] = {
            "sha256": hashlib.sha256(data).hexdigest(),
            "size": len(data),
            "pointerSize": 134,
        }
    return entry


def _tree_entry(repo: MockRepo, name: str, data: bytes) -> dict:
    entry: dict = {
        "type": "file",
        "path": name,
        "size": len(data),
        "oid": hashlib.sha1(data, usedforsecurity=False).hexdigest(),
    }
    if name in repo.lfs:
        entry["lfs"] = {
            "oid": hashlib.sha256(data).hexdigest(),
            "size": len(data),
            "pointerSize": 134,
        }
    return entry


def _file_headers(repo: MockRepo, filename: str, data: bytes) -> dict:
    etag = f'"{repo.blob_name(filename)}"'
    headers = {"ETag": etag, "X-Repo-Commit": repo.sha, "Accept-Ranges": "bytes"}
    if filename in repo.lfs:
        headers["X-Linked-Etag"] = etag
        headers["X-Linked-Size"] = str(len(data))
    return headers


@pytest.fixture
def mock_hf_hub():
    """Serve a mock hub on a free loopback port for the duration of one test."""
    hub = MockHfHub()
    hub.start()
    try:
        yield hub
    finally:
        hub.stop()


@pytest.fixture
def loopback_only(monkeypatch, hf_cache):
    """Refuse any socket or DNS lookup that is not loopback; turn off Xet and use small chunks.

    Every catalog id is a real repository id, so a call that forgets to pass the mock endpoint
    would otherwise talk to huggingface.co. Name resolution is blocked too, so such a call fails
    before it sends a byte. (Patching ``constants.ENDPOINT`` instead does not work: the library
    builds file URLs from a template computed at import and only substitutes ``endpoint=`` when
    the URL starts with the current ``ENDPOINT``, so a patched value silently sends the request
    to the real hub.) Xet is disabled through the environment as well, so a child process the
    test spawns speaks plain HTTP to the mock, and ambient token variables are removed.
    """
    from huggingface_hub import constants

    loopback = {"127.0.0.1", "::1", "localhost"}
    real_getaddrinfo = socket.getaddrinfo
    real_connect = socket.socket.connect

    def guarded_getaddrinfo(host, *args, **kwargs):
        if host not in loopback:
            raise OSError(f"test blocked a lookup of {host!r}")
        return real_getaddrinfo(host, *args, **kwargs)

    def guarded_connect(self, address):
        if isinstance(address, tuple) and address[0] not in loopback:
            raise OSError(f"test blocked a connection to {address[0]!r}")
        return real_connect(self, address)

    monkeypatch.setattr(socket, "getaddrinfo", guarded_getaddrinfo)
    monkeypatch.setattr(socket.socket, "connect", guarded_connect)
    monkeypatch.setattr(constants, "HF_HUB_DISABLE_XET", True)
    monkeypatch.setattr(constants, "DOWNLOAD_CHUNK_SIZE", 64 * 1024)
    monkeypatch.setenv("HF_HUB_DISABLE_XET", "1")
    # An ambient token (another test in this worker published one) would make a call that
    # passed none send an Authorization header, and the token assertions would flap.
    monkeypatch.delenv("HF_TOKEN", raising=False)
    monkeypatch.delenv("HUGGING_FACE_HUB_TOKEN", raising=False)
